create or replace function public.set_updated_at() returns trigger language plpgsql set search_path=public as $$ begin new.updated_at:=now();return new;end;$$;
create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at();
create trigger privacy_settings_updated_at before update on public.privacy_settings for each row execute function public.set_updated_at();
create trigger activities_updated_at before update on public.activities for each row execute function public.set_updated_at();
create trigger sos_requests_updated_at before update on public.sos_requests for each row execute function public.set_updated_at();
create trigger reports_updated_at before update on public.reports for each row execute function public.set_updated_at();
create trigger trusted_contacts_updated_at before update on public.trusted_contacts for each row execute function public.set_updated_at();
create trigger guardian_links_updated_at before update on public.guardian_links for each row execute function public.set_updated_at();
create trigger meeting_sessions_updated_at before update on public.meeting_sessions for each row execute function public.set_updated_at();

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
begin
 insert into public.profiles(id,name) values(new.id,nullif(trim(coalesce(new.raw_user_meta_data->>'name','')),'')) on conflict(id) do nothing;
 insert into public.privacy_settings(user_id) values(new.id) on conflict(user_id) do nothing;
 insert into public.user_presence(user_id,presence_status,visible) values(new.id,'offline',true) on conflict(user_id) do nothing;
 insert into public.trust_metrics(user_id) values(new.id) on conflict(user_id) do nothing;
 return new;
end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

create or replace function public.is_minor(target_user uuid) returns boolean language sql stable security definer set search_path=public as $$select coalesce((select p.birth_date>current_date-interval '18 years' from public.profiles p where p.id=target_user),false);$$;
create or replace function public.users_blocked(first_user uuid,second_user uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.blocks b where(b.blocker_id=first_user and b.blocked_id=second_user)or(b.blocker_id=second_user and b.blocked_id=first_user));$$;
create or replace function public.can_socially_interact(first_user uuid,second_user uuid) returns boolean language plpgsql stable security definer set search_path=public as $$
declare a date;b date;begin if first_user is null or second_user is null then return false;end if;if first_user=second_user then return true;end if;if public.users_blocked(first_user,second_user) then return false;end if;select birth_date into a from public.profiles where id=first_user;select birth_date into b from public.profiles where id=second_user;if a is null or b is null then return false;end if;return (a>current_date-interval '18 years')=(b>current_date-interval '18 years');end;$$;
create or replace function public.are_connected(first_user uuid,second_user uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.connections c where(c.user_a=first_user and c.user_b=second_user)or(c.user_a=second_user and c.user_b=first_user));$$;
create or replace function public.is_conversation_member(target_conversation uuid,target_user uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.conversation_members where conversation_id=target_conversation and user_id=target_user);$$;
create or replace function public.is_meeting_participant(target_meeting uuid,target_user uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.meeting_participants where meeting_id=target_meeting and user_id=target_user and status<>'cancelled');$$;

create or replace function public.set_presence(new_status text) returns void language plpgsql security definer set search_path=public as $$begin if new_status not in('online','away','offline') then raise exception 'Invalid presence status';end if;insert into public.user_presence(user_id,presence_status,last_seen,updated_at)values(auth.uid(),new_status,now(),now())on conflict(user_id)do update set presence_status=excluded.presence_status,last_seen=now(),updated_at=now();end;$$;
create or replace function public.set_visibility(new_visibility text) returns void language plpgsql security definer set search_path=public as $$begin if new_visibility not in('visible','connections','invisible') then raise exception 'Invalid visibility';end if;update public.privacy_settings set visibility=new_visibility,updated_at=now() where user_id=auth.uid();update public.user_presence set visible=(new_visibility='visible'),updated_at=now() where user_id=auth.uid();end;$$;
create or replace function public.set_my_location(lat double precision,lng double precision,gps_accuracy double precision default null) returns void language plpgsql security definer set search_path=public as $$declare privacy_mode text;begin if lat<-90 or lat>90 or lng<-180 or lng>180 then raise exception 'Invalid coordinates';end if;select visibility into privacy_mode from public.privacy_settings where user_id=auth.uid();insert into public.user_locations_private(user_id,location,accuracy,updated_at)values(auth.uid(),st_setsrid(st_makepoint(lng,lat),4326)::geography,gps_accuracy,now())on conflict(user_id)do update set location=excluded.location,accuracy=excluded.accuracy,updated_at=now();insert into public.user_presence(user_id,public_lat,public_lng,presence_status,visible,last_seen,updated_at)values(auth.uid(),round(lat::numeric,2)::double precision,round(lng::numeric,2)::double precision,'online',privacy_mode='visible',now(),now())on conflict(user_id)do update set public_lat=excluded.public_lat,public_lng=excluded.public_lng,presence_status='online',visible=excluded.visible,last_seen=now(),updated_at=now();end;$$;

create or replace function public.request_connection(target_user uuid,request_reason text default null) returns uuid language plpgsql security definer set search_path=public as $$declare me uuid:=auth.uid();rid uuid;begin if me is null then raise exception 'Not authenticated';end if;if target_user=me or not public.can_socially_interact(me,target_user) then raise exception 'Connection unavailable';end if;if public.are_connected(me,target_user) then raise exception 'Already connected';end if;if exists(select 1 from public.connection_requests where status='pending' and((sender_id=me and receiver_id=target_user)or(sender_id=target_user and receiver_id=me)))then raise exception 'Connection request already pending';end if;insert into public.connection_requests(sender_id,receiver_id,request_reason)values(me,target_user,nullif(trim(request_reason),''))returning id into rid;insert into public.notifications(user_id,actor_id,type,title,body,entity_type,entity_id)values(target_user,me,'connection_request','Nova solicitação','Uma pessoa quer se conectar com você.','connection_request',rid);return rid;end;$$;

create or replace function public.accept_connection_request(request_id uuid) returns uuid language plpgsql security definer set search_path=public as $$declare r public.connection_requests%rowtype;a uuid;b uuid;cid uuid;chat uuid;begin select * into r from public.connection_requests where id=request_id for update;if r.id is null or r.receiver_id<>auth.uid() or r.status<>'pending' then raise exception 'Request unavailable';end if;if not public.can_socially_interact(r.sender_id,r.receiver_id) then raise exception 'Connection unavailable';end if;if r.sender_id::text<r.receiver_id::text then a:=r.sender_id;b:=r.receiver_id;else a:=r.receiver_id;b:=r.sender_id;end if;select id into cid from public.connections where user_a=a and user_b=b;if cid is null then insert into public.connections(user_a,user_b)values(a,b)returning id into cid;end if;update public.connection_requests set status='accepted',responded_at=now() where id=request_id;select id into chat from public.conversations where connection_id=cid;if chat is null then insert into public.conversations(type,created_by,connection_id)values('dm',auth.uid(),cid)returning id into chat;end if;insert into public.conversation_members(conversation_id,user_id)values(chat,r.sender_id),(chat,r.receiver_id)on conflict do nothing;insert into public.notifications(user_id,actor_id,type,title,body,entity_type,entity_id)values(r.sender_id,auth.uid(),'connection_accepted','Conexão aceita','Sua solicitação de conexão foi aceita.','conversation',chat);return chat;end;$$;
create or replace function public.decline_connection_request(request_id uuid) returns void language plpgsql security definer set search_path=public as $$begin update public.connection_requests set status='declined',responded_at=now() where id=request_id and receiver_id=auth.uid() and status='pending';end;$$;

create or replace function public.offer_sos_help(target_sos uuid) returns uuid language plpgsql security definer set search_path=public as $$declare s public.sos_requests%rowtype;rid uuid;begin select * into s from public.sos_requests where id=target_sos;if s.id is null or s.status not in('looking','responses') or s.author_id=auth.uid() then raise exception 'SOS unavailable';end if;if not public.can_socially_interact(auth.uid(),s.author_id) then raise exception 'SOS unavailable';end if;insert into public.sos_responses(sos_id,helper_id,status)values(target_sos,auth.uid(),'offered')on conflict(sos_id,helper_id)do update set status='offered' returning id into rid;update public.sos_requests set status='responses' where id=target_sos and status='looking';insert into public.notifications(user_id,actor_id,type,title,body,entity_type,entity_id)values(s.author_id,auth.uid(),'sos_offer','Alguém quer ajudar','Uma usuária respondeu ao seu pedido no SOS Delas.','sos',target_sos);return rid;end;$$;

create or replace function public.accept_sos_help(target_response uuid) returns uuid language plpgsql security definer set search_path=public as $$declare r public.sos_responses%rowtype;s public.sos_requests%rowtype;chat uuid;begin select * into r from public.sos_responses where id=target_response for update;if r.id is null then raise exception 'Response unavailable';end if;select * into s from public.sos_requests where id=r.sos_id for update;if s.author_id<>auth.uid() or r.status<>'offered' then raise exception 'Not allowed';end if;insert into public.conversations(type,title,created_by)values('help','SOS Delas',auth.uid())returning id into chat;insert into public.conversation_members(conversation_id,user_id)values(chat,auth.uid()),(chat,r.helper_id);update public.sos_responses set status='accepted',responded_at=now(),conversation_id=chat where id=target_response;update public.sos_requests set status='in_progress' where id=r.sos_id;return chat;end;$$;

create or replace function public.refresh_trust_metrics(target_user uuid) returns void language plpgsql security definer set search_path=public as $$declare n integer;avg_rating numeric;begin select count(*),coalesce(avg(rating),0) into n,avg_rating from public.reviews where reviewed_user_id=target_user;insert into public.trust_metrics(user_id,trust_score,review_count,updated_at)values(target_user,round((avg_rating/5.0*100)::numeric,2),n,now())on conflict(user_id)do update set trust_score=excluded.trust_score,review_count=excluded.review_count,updated_at=now();end;$$;
create or replace function public.after_review_change() returns trigger language plpgsql security definer set search_path=public as $$begin perform public.refresh_trust_metrics(coalesce(new.reviewed_user_id,old.reviewed_user_id));return coalesce(new,old);end;$$;
create trigger reviews_refresh_trust after insert or update or delete on public.reviews for each row execute function public.after_review_change();

grant execute on function public.is_minor(uuid) to authenticated;
grant execute on function public.users_blocked(uuid,uuid) to authenticated;
grant execute on function public.can_socially_interact(uuid,uuid) to authenticated;
grant execute on function public.are_connected(uuid,uuid) to authenticated;
grant execute on function public.is_conversation_member(uuid,uuid) to authenticated;
grant execute on function public.is_meeting_participant(uuid,uuid) to authenticated;
grant execute on function public.set_presence(text) to authenticated;
grant execute on function public.set_visibility(text) to authenticated;
grant execute on function public.set_my_location(double precision,double precision,double precision) to authenticated;
grant execute on function public.request_connection(uuid,text) to authenticated;
grant execute on function public.accept_connection_request(uuid) to authenticated;
grant execute on function public.decline_connection_request(uuid) to authenticated;
grant execute on function public.offer_sos_help(uuid) to authenticated;
grant execute on function public.accept_sos_help(uuid) to authenticated;
